def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track recent opponent behavior with multiple windows
    opp_actions = [h[1] for h in history]
    my_actions = [h[0] for h in history]

    opp_coops = opp_actions.count('C')
    opp_defects = n - opp_coops
    opp_rate = opp_coops / n

    # Recent windows
    recent_n = min(n, 8)
    recent_opp = opp_actions[-recent_n:]
    recent_my = my_actions[-recent_n:]
    recent_opp_c = recent_opp.count('C')
    recent_opp_d = recent_n - recent_opp_c

    last_my, last_opp = history[-1]

    # Count consecutive opponent defections at end
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_actions[i] == 'D':
            opp_def_streak += 1
        else:
            break

    # Count consecutive opponent cooperations at end
    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if opp_actions[i] == 'C':
            opp_c_streak += 1
        else:
            break

    # Count mutual cooperation in recent window
    recent_mutual = sum(1 for i in range(n - recent_n, n) if history[i][0] == 'C' and history[i][1] == 'C')

    # Early game: cooperate to establish mutual cooperation
    if n < 4:
        return 'C'

    # Very cooperative opponent: maintain mutual cooperation, only punish sustained betrayal
    if opp_rate >= 0.85:
        if opp_def_streak >= 3:
            return 'D'
        # Very rare probe near end to test, but only if we've been highly cooperative
        if n >= 90 and opp_defects <= 1 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Highly cooperative opponent (70-85%)
    if opp_rate >= 0.7:
        if opp_def_streak >= 3:
            return 'D'
        # Forgive isolated defections quickly
        if last_opp == 'D':
            # One-round punishment then return to cooperation
            if last_my == 'D':
                return 'C'
            return 'D'
        return 'C'

    # Moderate cooperation (40-70%): generous tit-for-tat with repair
    if opp_rate >= 0.4:
        # If we've established mutual cooperation recently and opponent just defected,
        # give a warning shot then restore cooperation
        if last_opp == 'C':
            # Occasionally test but mostly cooperate
            if rng.random() < 0.03:
                return 'D'
            return 'C'

        # Opponent defected
        if last_my == 'D':
            # We already punished - return to cooperation to break retaliation cycle
            # But if opponent defected many times recently, continue punishment
            if recent_opp_d >= 5:
                return 'D'
            return 'C'

        # First defection: retaliate once
        if opp_def_streak >= 4:
            return 'D'
        return 'D'

    # Low cooperation (15-40%): mostly defect, but probe for renewal
    if opp_rate >= 0.15:
        # Try occasional cooperation to re-establish
        if opp_def_streak >= 5:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # If opponent recently cooperated a couple times, respond cooperatively
        if recent_opp_c >= 2 and last_opp == 'C':
            return 'C'
        # If we've been defecting long, try peace offering
        if recent_my.count('D') >= 4 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Very uncooperative: mostly defect, rare probes
    if opp_def_streak >= 8:
        if rng.random() < 0.1:
            return 'C'
        return 'D'
    if rng.random() < 0.08:
        return 'C'
    return 'D'
